//! Frozen channel/pool references on surveyed profiles.
//!
//! `CASES` of `reference.rs` hold on the surveyed `RECTANGLE_<b>` and `TRIANGLE_<s>`
//! profiles with `b` and `s` equal to `coefficient`: the 150-digit rows reproduce them.
//! `THREE_BANDS_CASES` add one 128 m cell of three bands at rest 1.5 m, `g = 1`,
//! `dt = 0.125 s`, and a constant-area pool. Leaving rows cross knot 1. Entering rows
//! cross knot 2. The opposite end holds the interior state at rest, so its face carries
//! the interior pressure only.

// Generated by `transcribe.py` in `resource/evidence/surveyed-endpoints/` from its
// frozen `reference.json`. Regenerate instead of editing.

use super::reference::Expected;
use super::surveyed_profiles::{Profile, THREE_BANDS};

#[derive(Clone, Copy, Debug)]
pub struct SurveyedCase {
    pub name: &'static str,
    pub profile: Profile,
    pub gravity: f64,
    pub interior_area_m2: f64,
    pub cell_length_m: f64,
    pub elevation: f64,
    pub loss: f64,
    pub pool_area: f64,
    pub dt: f64,
    /// Nearest binary64 of each 150-digit reference.
    pub expected: Expected,
}

