#[test]
fn surveyed_channel_pool_references_load() {
    for case in THREE_BANDS_CASES {
        assert!(f64::from_bits(case.profile.cap) > case.expected.depth);
        assert!(case.expected.pool_volume > 0.0 && case.expected.channel_volume > 0.0);
    }
}
